function render(full=true){renderArt();viewport();overlay();if(!full)return;renderLayers();renderInspector();$('projectName').value=project.name;$('canvasWidth').value=project.canvas.width;$('canvasHeight').value=project.canvas.height;$('transparent').checked=project.canvas.background==='transparent';$('canvasBackground').value=project.canvas.background==='transparent'?'#ffffff':project.canvas.background;$('undo').disabled=!history.past.length;$('redo').disabled=!history.future.length;$('animationSection').hidden=!project.animation.enabled;$('animDuration').value=project.animation.duration;$('animFps').value=project.animation.fps;$('animAmplitude').value=project.animation.amplitude;frameUI();updateActions();}
function updateActions(){const unlocked=selection.filter(id=>!C.isLocked(project,project.objects.find(o=>o.id===id)));for(const id of ['duplicate','delete','layerUp','layerDown'])$(id).disabled=!selection.length;$('group').disabled=unlocked.length<2;$('ungroup').disabled=selection.length!==1||current()?.type!=='group';$('finishPath').disabled=!penId;$('closePath').disabled=!(current()?.type==='path'&&!C.isLocked(project,current()));$('addNode').disabled=$('deleteNode').disabled=tool!=='node'||current()?.type!=='path'||nodeIndex<0||C.isLocked(project,current());document.querySelectorAll('[data-align]').forEach(b=>b.disabled=!unlocked.length);document.querySelectorAll('[data-distribute]').forEach(b=>b.disabled=unlocked.length<3);$('makeSticker').disabled=!selection.length;$('layerGroup').disabled=$('group').disabled;$('layerUngroup').disabled=$('ungroup').disabled||!!current()?.maskId;$('layerDelete').disabled=!selection.length;const masked=toggleMaskGroup(),maskButton=$('createMask');maskButton.disabled=masked?C.isLocked(project,masked):selection.length<1||selection.length>2||!unlocked.length;maskButton.setAttribute('aria-pressed',String(!!masked));maskButton.classList.toggle('active',!!masked);maskButton.title=masked?'解除蒙版：保留原图与形状':'建立蒙版：上方内容使用下方闭合形状裁剪';}
function renderLayers(){const scroll=$('layers').scrollTop;const icon=window.PosterUI.icon;function rows(parent=null,depth=0){return project.objects.filter(o=>o.parentId===parent).reverse().map(o=>`<div class="layer ${selection.includes(o.id)?'selected':''} ${o.visible?'':'dim'}" data-layer="${o.id}" draggable="false" role="listitem" aria-label="${e(o.name)}" style="padding-left:${depth*12+3}px"><button class="fold ${collapsed.has(o.id)?'':'open'}" ${o.type==='group'?`data-fold="${o.id}" aria-label="${collapsed.has(o.id)?'展开':'折叠'}组合"`:'disabled aria-hidden="true"'}>${o.type==='group'?icon('chevron'):''}</button><span class="layer-type">${icon(o.maskId?'mask':o.type==='path'?'pen':o.type)}</span><span class="lname" title="双击重命名">${e(o.name)}</span>${project.objects.some(n=>n.maskId===o.id)?'<span class="mask-badge">蒙版</span>':''}<button data-delete-layer="${o.id}" title="删除图层" aria-label="删除 ${e(o.name)}">${icon('trash')}</button><button data-visibility="${o.id}" title="${o.visible?'隐藏':'显示'}图层" aria-label="${o.visible?'隐藏':'显示'} ${e(o.name)}">${icon(o.visible?'eye':'hidden')}</button><button data-lock="${o.id}" title="${o.locked?'解锁':'锁定'}图层" aria-label="${o.locked?'解锁':'锁定'} ${e(o.name)}">${icon(o.locked?'lock':'unlock')}</button></div>${o.type==='group'&&!collapsed.has(o.id)?rows(o.id,depth+1):''}`).join('');}$('layers').innerHTML=rows();$('layers').scrollTop=scroll;$('layerCount').textContent=project.objects.length;if(!project.objects.length)$('layers').innerHTML='<p class="hint" style="padding:8px">还没有图层。选择左侧工具，在画布创建对象。</p>';}
const field=(label,key,value,type='number',extra='')=>`<label>${e(label)}<input data-prop="${key}" aria-label="${e(label)}" type="${type}" value="${e(value)}" ${extra}></label>`;
const check=(label,key,value)=>`<label class="inline"><input data-prop="${key}" aria-label="${e(label)}" type="checkbox" ${value?'checked':''}>${e(label)}</label>`;
const options=(label,key,value,items)=>`<label>${e(label)}<select data-prop="${key}" aria-label="${e(label)}">${items.map(([v,n])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(n)}</option>`).join('')}</select></label>`;
const defaultPaint=()=>C.createObject('rect').fillPaint;
const paintOf=o=>{const base=defaultPaint(),paint=o.fillPaint||{},gradient={...base.gradient,...paint.gradient};gradient.stops=C.gradientStops(gradient).map(s=>({...s}));return{...base,...paint,gradient,pattern:{...base.pattern,...paint.pattern}};};
function syncGradientEndpoints(g){const stops=C.gradientStops(g);g.from=stops[0].color;g.to=stops.at(-1).color;}
function gradientEditor(o){const g=paintOf(o).gradient,stops=C.gradientStops(g),id=gradientStopSelection.get(o.id)||stops[0].id,active=stops.find(s=>s.id===id)||stops[0];gradientStopSelection.set(o.id,active.id);const ramp=stops.map(s=>s.color+' '+Math.round(s.position*100)+'%').join(', ');return `${options('渐变模板','@gradientPreset','custom',[['custom','自定义'],['warm','暖色'],['cool','冷色'],['ink','黑白'],...(project.style.gradientPresets||[]).map(p=>[p.id,p.name])])}<button data-action="saveGradientPreset">保存当前渐变为模板</button>${options('渐变形状','fillPaint.gradient.kind',g.kind,[['linear','线形'],['radial','放射形'],['conic','衍射形／角度']])}<div class="gradient-bar" data-gradient-bar style="background:linear-gradient(to right,${e(ramp)})" title="点击色带添加颜色节点">${stops.map(s=>`<button type="button" class="gradient-stop ${s.id===active.id?'active':''}" data-gradient-stop="${e(s.id)}" style="left:${s.position*100}%;background:${e(s.color)}" title="${Math.round(s.position*100)}% · ${e(s.color)}"></button>`).join('')}</div><div class="two">${field('节点颜色','@stopColor',active.color,'color')}${field('节点位置（%）','@stopPosition',Math.round(active.position*100),'number','min="0" max="100" step="1"')}</div><button type="button" data-action="deleteGradientStop" ${stops.length<=2?'disabled':''}>删除当前颜色节点</button>${field('方向（°）','fillPaint.gradient.angle',g.angle,'number','min="-360" max="360" step="1"')}${check('反向','fillPaint.gradient.reverse',g.reverse)}`;}
function renderInspector(){const o=current();if(!o){updateInspector('<p class="hint">选择对象以编辑属性。</p>');return;}const b=C.union(selection.map(id=>C.bounds(project,project.objects.find(o=>o.id===id))));let html=selection.length===1?field('图层名称','name',o.name,'text'): `<p class="hint">已选择 ${selection.length} 个对象，外观设置应用到所有选中对象。</p>`;
html+=`<div class="two">${field('X','@x',Math.round(b.x*100)/100)}${field('Y','@y',Math.round(b.y*100)/100)}${field('宽度','@w',Math.round((selection.length===1&&o.type==='text'?o.w:b.w)*100)/100,'number','min="0.01" step="0.1"')}${field('高度','@h',Math.round((selection.length===1&&o.type==='text'?o.h:b.h)*100)/100,'number','min="0.01" step="0.1"')}</div><label class="inline"><input id="keepRatio" type="checkbox" ${keepRatio()?'checked':''}>${selection.length===1&&o.type==='text'?'锁定文字框比例':selection.length>1?'多选整体等比缩放':'等比缩放'}</label>${field('旋转角度','@rotation',Math.round(Math.atan2(o.m[1],o.m[0])*180/Math.PI),'number','step="1"')}<div class="grid"><button data-action="flipX">水平翻转</button><button data-action="flipY">垂直翻转</button><button data-action="skew" aria-pressed="${transformMode==='skew'}" class="${transformMode==='skew'?'active':''}">斜切</button><button data-action="perspective" aria-pressed="${transformMode==='perspective'}" class="${transformMode==='perspective'?'active':''}" ${selection.length!==1?'disabled title="透视需要单选一个对象"':''}>透视</button></div>`;
if(selection.length===1&&o.type==='text'){html+=`<label>文字内容<textarea data-prop="text" aria-label="文字内容">${e(o.text)}</textarea></label>${fontPicker(o)}<div class="two">${field('字号','fontSize',o.fontSize,'number','min="1" max="2000"')}${options('字重','fontWeight',o.fontWeight,[[300,'细'],[400,'常规'],[500,'中'],[600,'半粗'],[700,'粗'],[900,'黑']])}${field('字距','letterSpacing',o.letterSpacing,'number','step="0.5"')}${field('行距倍数','lineHeight',o.lineHeight,'number','min="0.2" max="10" step="0.1"')}</div>${options('字形','fontStyle',o.fontStyle,[['normal','常规'],['italic','斜体']])}${options('段落对齐','textAlign',o.textAlign,[['left','左'],['center','中'],['right','右']])}<p class="hint">拖动边角只调整文字框，文字自动换行；字号保持不变。超出高度会裁切。</p>`;}
if(selection.length===1&&o.type==='image')html+=`<button data-action="replaceImage">替换图片</button>${sectionStart("crop")}<summary>图片裁切（源图比例）</summary><div class="two">${['x','y','w','h'].map(k=>field(({x:'左侧',y:'顶部',w:'裁切宽度',h:'裁切高度'})[k],'crop.'+k,o.crop[k],'number','min="0" max="1" step="0.01"')).join('')}</div><button data-action="resetCrop">重置裁切</button></details>`;
if(['polygon','star'].includes(o.type))html+=field('边／角数量','sides',o.sides,'number','min="3" max="100" step="1"');
if(o.type==='path')html+=check('闭合路径','closed',o.closed);
if(o.type!=='image'&&o.type!=='group'){const paint=paintOf(o),g=paint.gradient,t=paint.pattern;html+=`${sectionStart("fill")}<summary>填充与描边</summary>${check('启用填充','@fillOn',o.fill!=='none')}${options('填充类型','fillPaint.type',paint.type,[['solid','纯色'],['gradient','渐变'],['pattern','图案']])}${paint.type==='solid'?field('填充颜色','fill',o.fill==='none'?'#282c38':o.fill,'color'):''}${paint.type==='gradient'?gradientEditor(o):''}${paint.type==='pattern'?`<button data-action="uploadPattern">${t.assetId?'替换图案图片':'上传 PNG / JPG 图案'}</button><p class="hint">图案会按原图平铺；源图片边缘若不衔接，接缝仍可见。</p>${field('图案比例','fillPaint.pattern.scale',t.scale,'number','min="0.01" max="20" step="0.05"')}${field('图案旋转（°）','fillPaint.pattern.rotation',t.rotation,'number','min="-360" max="360" step="1"')}`:''}${field('描边颜色','stroke',o.stroke==='none'?'#282c38':o.stroke,'color')}${field('描边宽度','strokeWidth',o.strokeWidth,'number','min="0" max="1000" step="0.5"')}${options('线端','linecap',o.linecap,[['round','圆头'],['butt','平头'],['square','方头']])}${options('连接','linejoin',o.linejoin,[['round','圆角'],['miter','尖角'],['bevel','斜角']])}</details>`;}
if(o.type==='image')html+=`${sectionStart('stroke')}<summary>描边</summary>${field('描边颜色','stroke',o.stroke==='none'?'#282c38':o.stroke,'color')}${field('描边宽度','strokeWidth',o.strokeWidth,'number','min="0" max="1000" step="0.5"')}<p class="hint">沿图片可见像素的边缘描边，透明区域保留。</p></details>`;
html+=options('图层混合模式','blendMode',o.blendMode||'normal',[['normal','正常'],['multiply','正片叠底'],['screen','滤色'],['overlay','叠加'],['plus-lighter','线性减淡（添加）'],['plus-darker','线性加深']]);html+=field('透明度','opacity',o.opacity,'range','min="0" max="1" step="0.01"');for(const key of ['shadow','glow']){const effect=o[key];html+=`${sectionStart(key)}<summary>${key==='shadow'?'投影':'发光'}</summary>${check('启用'+(key==='shadow'?'投影':'发光'),key+'.enabled',effect.enabled)}${field(key==='shadow'?'投影颜色':'发光颜色',key+'.color',effect.color,'color')}${field(key==='shadow'?'投影模糊':'发光模糊',key+'.blur',effect.blur,'number','min="0" max="500"')}${field(key==='shadow'?'投影透明度':'发光透明度',key+'.opacity',effect.opacity,'range','min="0" max="1" step="0.01"')}${key==='shadow'?`<div class="two">${field('投影 X',key+'.x',effect.x)}${field('投影 Y',key+'.y',effect.y)}</div>`:''}</details>`;}
html+=check('锁定对象','locked',o.locked);updateInspector(html);}
$('inspector').addEventListener('input',ev=>{const el=ev.target,key=el.dataset.prop;if(!key||el.type==='checkbox'||el.tagName==='SELECT')return;guard(()=>{if(el.type==='number'&&el.value==='')return;liveInput=el;try{applyProperty(key,el.type==='number'||el.type==='range'?Number(el.value):el.value,keepRatio());}finally{liveInput=null;}});});
function selectedBounds(){return C.union(selection.map(id=>C.bounds(project,project.objects.find(o=>o.id===id))));}
function applyProperty(key,value,keepRatio){const beforeBounds=selectedBounds();commit(()=>{if(key.startsWith('@')){const b=beforeBounds;if(key==='@x'||key==='@y')C.transformObjects(project,selection,C.translate(key==='@x'?value-b.x:0,key==='@y'?value-b.y:0));if(key==='@w'||key==='@h'){if(selection.length===1&&current()?.type==='text'){const o=current(),ratio=value/(key==='@w'?o.w:o.h);C.resizeTextBox(project,o.id,key==='@w'?value:keepRatio?o.w*ratio:o.w,key==='@h'?value:keepRatio?o.h*ratio:o.h);return;}if((key==='@w'?b.w:b.h)<.001)throw Error('零尺寸方向不能缩放');let sx=key==='@w'?value/b.w:1,sy=key==='@h'?value/b.h:1;if(keepRatio){if(key==='@w')sy=sx;else sx=sy;}C.resizeObjects(project,selection,C.around(b.x,b.y,sx,sy));}if(key==='@rotation'){const o=current(),old=Math.atan2(o.m[1],o.m[0])*180/Math.PI;C.transformObjects(project,selection,C.around(b.x+b.w/2,b.y+b.h/2,1,1,value-old));}if(key==='@fillOn')for(const id of selection){const o=project.objects.find(n=>n.id===id);o.fill=value?'#282c38':'none';}if(key==='@gradientPreset'){const built={warm:['#ff6a3d','#ffdc66'],cool:['#1658d7','#75e9f4'],ink:['#111111','#ffffff']},custom=project.style.gradientPresets?.find(p=>p.id===value);for(const id of selection){const o=project.objects.find(n=>n.id===id);o.fillPaint=C.clone(paintOf(o));const g=o.fillPaint.gradient;if(custom?.gradient)Object.assign(g,C.clone(custom.gradient));else {const colors=built[value]||custom?.colors;if(!colors)continue;g.from=colors[0];g.to=colors.at(-1);g.stops=colors.map((color,i)=>({id:C.uid(),position:i/(colors.length-1),color}));}gradientStopSelection.set(o.id,g.stops[0].id);}}if(key==='@stopColor'||key==='@stopPosition')for(const id of selection){const o=project.objects.find(n=>n.id===id);o.fillPaint=paintOf(o);const stops=o.fillPaint.gradient.stops,stop=stops.find(n=>n.id===gradientStopSelection.get(id))||stops[0];if(key==='@stopColor')stop.color=value;else stop.position=Math.max(0,Math.min(1,value/100));syncGradientEndpoints(o.fillPaint.gradient);}}else for(const id of selection){const o=project.objects.find(n=>n.id===id),parts=key.split('.');if(parts[0]==='fillPaint')o.fillPaint=paintOf(o);let target=o;for(const part of parts.slice(0,-1))target=target[part];target[parts.at(-1)]=value;}});}
$('inspector').addEventListener('change',ev=>guard(()=>{const el=ev.target,key=el.dataset.prop;if(el.id==='keepRatio'){setInspectorState('keepRatio',el.checked);return;}if(!key)return;if(key==='fillPaint.type'&&el.value==='pattern'&&selection.some(id=>!paintOf(project.objects.find(o=>o.id===id)).pattern.assetId)){patternIntent=[...selection];$('patternFile').click();renderInspector();return;}if(lastInput===el){lastInput=null;render();return;}const ratio=keepRatio(),value=el.type==='checkbox'?el.checked:el.type==='number'||el.type==='range'||key==='fontWeight'?Number(el.value):el.value;applyProperty(key,value,ratio);}));
function gradientBarPosition(bar,clientX){const r=bar.getBoundingClientRect();return Math.max(0,Math.min(1,(clientX-r.left)/r.width));}
$('inspector').addEventListener('pointerdown',ev=>{const stop=ev.target.closest('[data-gradient-stop]');if(!stop||ev.button!==0||!current())return;ev.preventDefault();gradientStopSelection.set(current().id,stop.dataset.gradientStop);gradientDrag={id:current().id,stopId:stop.dataset.gradientStop,before:C.clone(project),bar:stop.closest('[data-gradient-bar]'),moved:false};current().fillPaint=paintOf(current());$('inspector').setPointerCapture(ev.pointerId);stop.closest('[data-gradient-bar]').querySelectorAll('[data-gradient-stop]').forEach(n=>n.classList.toggle('active',n===stop));});
$('inspector').addEventListener('pointermove',ev=>{if(!gradientDrag)return;const d=gradientDrag,o=project.objects.find(n=>n.id===d.id);if(!o)return;const pos=gradientBarPosition(d.bar,ev.clientX),stop=o.fillPaint.gradient.stops.find(n=>n.id===d.stopId);if(!stop)return;stop.position=pos;syncGradientEndpoints(o.fillPaint.gradient);d.moved=true;renderArt();overlay();const bar=$('inspector').querySelector('[data-gradient-bar]');if(bar){const handle=bar.querySelector('[data-gradient-stop="'+d.stopId+'"]');if(handle)handle.style.left=(pos*100)+'%';const g=paintOf(o).gradient;bar.style.background='linear-gradient(to right,'+C.gradientStops(g).map(n=>n.color+' '+Math.round(n.position*100)+'%').join(', ')+')';}});
$('inspector').addEventListener('pointerup',()=>{if(!gradientDrag)return;const d=gradientDrag;gradientDrag=null;if(d.moved){history.push(d.before);markDirty();render();}else renderInspector();});
$('inspector').addEventListener('click',ev=>guard(async()=>{const bar=ev.target.closest('[data-gradient-bar]');if(bar&&!ev.target.closest('[data-gradient-stop]')&&current()){const pos=gradientBarPosition(bar,ev.clientX),o=current(),g=paintOf(o).gradient,color=R.colorAt(C.gradientStops(g),pos),id=C.uid();commit(()=>{o.fillPaint=paintOf(o);o.fillPaint.gradient.stops.push({id,position:pos,color});gradientStopSelection.set(o.id,id);});return;}const action=ev.target.dataset.action;if(!action)return;if(action==='skew'||action==='perspective'){contextAction(action);return;}if(action==='replaceImage'){imageIntent=current().id;$('imageFile').click();return;}if(action==='uploadPattern'){patternIntent=[...selection];$('patternFile').click();return;}if(action==='saveGradientPreset'){const name=await ask('渐变模板名称','我的渐变');if(!name)return;const g=paintOf(current()).gradient;commit(()=>{project.style.gradientPresets||=[];project.style.gradientPresets.push({id:C.uid(),name,colors:C.gradientStops(g).map(s=>s.color),gradient:C.clone(g)});});return;}if(action==='deleteGradientStop'){const o=current(),id=gradientStopSelection.get(o.id);if(C.gradientStops(paintOf(o).gradient).length<=2)return;commit(()=>{o.fillPaint=paintOf(o);o.fillPaint.gradient.stops=o.fillPaint.gradient.stops.filter(s=>s.id!==id);syncGradientEndpoints(o.fillPaint.gradient);gradientStopSelection.set(o.id,C.gradientStops(o.fillPaint.gradient)[0].id);});return;}commit(()=>{if(action==='resetCrop')current().crop={x:0,y:0,w:1,h:1};else{const b=selectedBounds();C.transformObjects(project,selection,C.around(b.x+b.w/2,b.y+b.h/2,action==='flipX'?-1:1,action==='flipY'?-1:1));}});}));
$('layers').addEventListener('click',ev=>guard(()=>{if(suppressLayerClick)return;const el=ev.target.closest('button')||ev.target;if(el.dataset.deleteLayer){commit(()=>{C.remove(project,[el.dataset.deleteLayer]);selection=selection.filter(id=>project.objects.some(o=>o.id===id));});return;}if(el.dataset.fold){collapsed.has(el.dataset.fold)?collapsed.delete(el.dataset.fold):collapsed.add(el.dataset.fold);renderLayers();return;}if(el.dataset.visibility){commit(()=>{const o=project.objects.find(n=>n.id===el.dataset.visibility);o.visible=!o.visible;});return;}if(el.dataset.lock){commit(()=>{const o=project.objects.find(n=>n.id===el.dataset.lock);o.locked=!o.locked;});return;}const row=el.closest('[data-layer]');if(row){const id=row.dataset.layer;if(editingGroup&&!insideGroup(project.objects.find(o=>o.id===id)))editingGroup=null;if(ev.shiftKey&&layerAnchor){const visible=[...$('layers').querySelectorAll('[data-layer]')].map(n=>n.dataset.layer),a=visible.indexOf(layerAnchor),b=visible.indexOf(id);selection=a<0?[id]:C.topIds(project,visible.slice(Math.min(a,b),Math.max(a,b)+1));}else if(ev.ctrlKey||ev.metaKey)selection=selection.includes(id)?selection.filter(x=>x!==id):C.topIds(project,[...selection,id]);else selection=[id];if(!ev.shiftKey)layerAnchor=id;$('workspace').focus({preventScroll:true});nodeIndex=-1;renderArt();viewport();overlay();renderInspector();updateActions();$('layers').querySelectorAll('[data-layer]').forEach(n=>n.classList.toggle('selected',selection.includes(n.dataset.layer)));}}));
$('layers').addEventListener('dblclick',ev=>guard(async()=>{if(!ev.target.closest('.lname'))return;const id=ev.target.closest('[data-layer]').dataset.layer,o=project.objects.find(n=>n.id===id),name=await ask('图层名称',o.name);if(name!==null)commit(()=>{const target=project.objects.find(n=>n.id===id);if(target)target.name=name;});}));
function clearLayerDrop(){$('layers').querySelectorAll('.drop-before,.drop-after,.drop-inside').forEach(n=>n.classList.remove('drop-before','drop-after','drop-inside'));$('layerRootDrop').classList.remove('drop-inside');}
$('layers').addEventListener('pointerdown',ev=>{if(ev.button!==0||ev.target.closest('button'))return;const row=ev.target.closest('[data-layer]');if(!row)return;layerDrag={id:row.dataset.layer,x:ev.clientX,y:ev.clientY,moved:false};});
